import datetime
import math
import re
import polars as pl


def transform(raw: pl.DataFrame) -> pl.DataFrame:
    missing = ["", "N/A", "n/a", "-", "null", "NULL", "None"]

    def clean_str(col: str) -> pl.Expr:
        s = pl.col(col).str.strip_chars()
        return pl.when(s.is_in(missing)).then(None).otherwise(s)

    def parse_number(col: str) -> pl.Expr:
        cleaned = clean_str(col).str.replace(",", ".", global=True)
        return cleaned.cast(pl.Float64, strict=False).round(2)

    return raw.select(
        employee_id=clean_str("Employee ID").str.to_uppercase(),
        employee_name=clean_str("Employee"),
        work_date=clean_str("Date").str.to_date("%d/%m/%Y", strict=False),
        project_code=clean_str("Project").str.to_uppercase(),
        hours_normal=parse_number("Hours"),
        hours_overtime=parse_number("Overtime Hours"),
    )
